pages.script:
const toast=document.querySelector('#toast');let timer;function show(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2500)}
document.querySelector('#eye').addEventListener('click',()=>{const input=document.querySelector('#password');input.type=input.type==='password'?'text':'password';document.querySelector('#eye').setAttribute('aria-label',input.type==='password'?'显示密码':'隐藏密码')});
document.querySelector('#form').addEventListener('submit',event=>{event.preventDefault();show('这是设计稿 HTML 演示，未连接登录接口。')});
document.querySelectorAll('[data-message]').forEach(item=>item.addEventListener('click',event=>{event.preventDefault();show(item.dataset.message)}));

const toast=document.querySelector('#toast');let timer;function show(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2500)}
document.querySelector('#send-code').addEventListener('click',()=>show('这是设计稿演示，暂未发送验证码。'));
document.querySelector('#eye').addEventListener('click',()=>{const field=document.querySelector('#password');field.type=field.type==='password'?'text':'password';document.querySelector('#eye').setAttribute('aria-label',field.type==='password'?'显示密码':'隐藏密码')});
document.querySelector('#register').addEventListener('submit',event=>{event.preventDefault();show('这是设计稿演示，暂未连接注册接口。')});

const toast=document.querySelector('#toast');let timer;function show(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2500)}
document.querySelector('#send').addEventListener('click',()=>show('这是设计稿演示，暂未发送验证码。'));
document.querySelector('#recovery').addEventListener('submit',event=>{event.preventDefault();location.href='m01-p05.html'});

const toast=document.querySelector('#toast');let timer;function show(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelectorAll('.eye').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.target);input.type=input.type==='password'?'text':'password';button.setAttribute('aria-label',input.type==='password'?'显示密码':'隐藏密码')}));
document.querySelector('#reset').addEventListener('submit',event=>{event.preventDefault();const p=document.querySelector('#password').value,c=document.querySelector('#confirm').value;if(p!==c){show('两次输入的密码不一致');return}if(!/[A-Za-z]/.test(p)||!/[0-9]/.test(p)){show('密码需要包含字母和数字');return}show('这是设计稿演示，暂未连接密码重置接口。')});
